def rep_ratio(s):
    toks = s.split()
    if not toks:
        return 0.0
    return 1.0 - len(set(toks)) / len(toks)

samples = [
    "短",
    "机器学习是让计算机从数据中学习的技术机器学习是让计算机从数据中学习的技术机器学习是让计算机从数据中学习的技术",
    "过拟合指模型在训练集表现好但在测试集表现差的现象，通常由容量过大引起。",
    "aaaa bbbb aaaa bbbb aaaa bbbb",
]
MIN_LEN, MAX_LEN, MAX_REP = 4, 60, 0.5
kept = []
for s in samples:
    if MIN_LEN <= len(s) <= MAX_LEN and rep_ratio(s) <= MAX_REP:
        kept.append(s)
print(f"保留 {len(kept)}/{len(samples)}")
for s in kept:
    print("-", s)
